select uc.cert_id, uc.cert_code, uc.cert_name, uc.cert_url, uc.issuance_date, uc.cert_period, uc.acquire_way, uc.competition_series_id, uc.competition_track_id, uc.second_level_code, uc.course_id, uc.training_program_id, uc.cert_exchange_id, uc.cert_status, uc.team_code, uc.awards_name, uc.org_code, uc.create_by, uc.create_time, uc.update_by, uc.update_time, uc.del_flag, uc.version,uc.year, uc.competition_stage_id,csc.stage_name as competition_stage_name, (select distinct school from competition_apply_info where team_code = uc.team_code) school_id,uc.user_id,uc.cert_config_id, uc.id_card, uc.user_name, uc.player,uc.guide_teacher, csi.competition_series_name,csi.competition_name,cti.competition_track_name,ctc.second_level_name,coi.org_name from user_certificate uc LEFT JOIN competition_stage_config csc on csc.stage_id = uc.competition_stage_id left join (select a.competition_series_id, a.competition_series_name,b.competition_name from competition_series_info a left join competition_main_info b on a.competition_id = b.competition_id) csi on uc.competition_series_id = csi.competition_series_id left join competition_track_info cti on uc.competition_track_id = cti.competition_track_id left join competition_track_config ctc on uc.second_level_code = ctc.second_level_code left join cert_org_info coi on uc.org_code = coi.org_code where uc.del_flag = '0'
and uc.user_id = #{userId}
and uc.id_card = #{idCard}
and uc.issuance_date >= #{issuanceStartTime}
and uc.issuance_date <= #{issuanceEndTime}
and (uc.cert_name like concat('%',#{keyWords},'%') or coi.org_name like concat('%',#{keyWords},'%') or uc.user_name like concat('%',#{keyWords},'%') or uc.team_code in (select distinct team_code from competition_apply_info where user_name like concat('%',#{keyWords},'%')))
