and uco.user_id = #{userId}
and uco.id_card = #{idCard}
and uco.issuance_date >= #{issuanceStartTime}
and uco.issuance_date <= #{issuanceEndTime}
and (uco.cert_name like concat('%',#{keyWords},'%') or coi.org_name like concat('%',#{keyWords},'%') or uco.user_name like concat('%',#{keyWords},'%') or uco.team_code in (select distinct team_code from competition_apply_info where user_name like concat('%',#{keyWords},'%')))

