and uco.ert_code = #{certCode}
and uco.cert_name like concat('%', #{certName}, '%')
and uco.acquire_way = #{acquireWay}
and uco.competition_series_id = #{competitionSeriesId}
and uco.competition_track_id = #{competitionTrackId}
and uco.second_level_code = #{secondLevelCode}
and uco.course_id = #{courseId}
and uco.training_program_id = #{trainingProgramId}
and uco.cert_status = #{certStatus}
and uco.team_code = #{teamCode}
and uco.awards_name = #{awardsName}
and uco.year = #{year}
and uco.org_code = #{orgCode}
and uco.player like concat('%', #{player}, '%')
and uco.user_name like concat('%', #{userName}, '%')
and uco.id_card = #{idCard}
and uco.guide_teacher like concat('%', #{guideTeacher}, '%')
and uco.school_name like concat('%', #{schoolName}, '%')
ORDER BY create_time IS NULL,create_time DESC

