update user_certificate
cert_code = #{certCode}, cert_name = #{certName}, cert_url = #{certUrl}, issuance_date = #{issuanceDate}, cert_period = #{certPeriod}, acquire_way = #{acquireWay}, competition_stage_id = #{competitionStageId}, competition_track_id = #{competitionTrackId}, second_level_code = #{secondLevelCode}, course_id = #{courseId}, training_program_id = #{trainingProgramId}, cert_exchange_id = #{certExchangeId}, cert_status = #{certStatus}, team_code = #{teamCode}, awards_name = #{awardsName}, org_code = #{orgCode}, year = #{year}, cert_config_id = #{certConfigId}, id_card = #{idCard}, user_name = #{userName}, player = #{player}, guide_teacher = #{guideTeacher}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag}, version = version+1,
where cert_id = #{certId} and user_id = #{userId} and competition_series_id = #{competitionSeriesId}

update user_certificate
cert_url = #{certUrl}, update_time = now(), version = version+1,
where cert_config_id = #{certConfigId}
